#include<bits/stdc++.h>

using namespace std;

class ThoiGian{
	private:
		int gio;
		int phut;
		int giay;
	public:
		ThoiGian (){
			this->gio = 0;
			this->phut = 0;
			this->giay = 0;
		}
		void chuanHoa(){
			if(giay > 0){
				phut = phut + (giay/60);
				giay = giay % 60;
			}
			if(phut > 0){
				gio = gio + (phut/60);
				phut = phut % 60;
			}
		}
		friend istream& operator >>(istream &is, ThoiGian &tg){
			cout << "\nNhap thoi gian: ";
			is >> tg.gio >> tg.phut >> tg.giay;
			tg.chuanHoa();
			return is;
		}
		friend ostream& operator <<(ostream &os, const ThoiGian &tg){
			cout << "\nThoi gian: ";
			os << tg.gio << tg.phut << tg.giay;
			return os;
		}
		bool operator <(const ThoiGian &tg) const {
		    return (this->gio < tg.gio ||
		           (this->gio == tg.gio && this->phut < tg.phut) ||
		           (this->gio == tg.gio && this->phut == tg.phut && this->giay < tg.giay));
		}
		ThoiGian& operator +=(int s) {
		    this->giay += s;
		    this->chuanHoa();
		    return *this;
		}
};

void ketLuanSS(const ThoiGian &t1, const ThoiGian &t2){
	if(t1 < t2){
		cout << "t1 < t2\n";
	}
	else{
		cout << "t1 >= t2\n";
	}
}

int main(){
	ThoiGian t1, t2;
	cout << "\nNhap thoi gian 1:\n";
	cin >> t1;
	cout << "\nNhap thoi gian 2:\n";
	cin >> t2;
	cout << "\n=> Thoi gian 1:\n";
	cout << t1;
	cout << "\n=> Thoi gian 2:\n";
	cout << t2;
	cout << endl;
	ketLuanSS(t1, t2);
	int s;
	cout << "\nNhap s = ";
	cin >> s;	
	t1 += s;
	cout << "\n=> Thoi gian 1:\n";
	cout << t1;
	return 0;
}

